mapper.select:
SELECT c.content_id ,c.title ,c.body ,c.content_type ,ci.code_item_name AS content_type_name ,cgi.code_group_name AS group_name ,REPLACE(c.content_link, 'http://mepv2.safekorea.go.kr', '') AS content_link ,c.ordering ,c.visible_yn ,c.last_sync_yn ,c.reg_type ,c.created_at FROM content c LEFT JOIN code_item ci ON c.content_type = ci.code_item_id LEFT JOIN code_group cgi ON ci.code_group_id = cgi.code_group_id
AND cgi.code_group_id LIKE 'BEHAVIOR_METHOD_%'
AND c.content_type = #{contentType}
AND (c.last_sync_yn = 'Y' OR c.reg_type = 'MANUAL')
AND c.visible_yn = #{visibleYn}
ORDER BY c.content_type ASC, c.ordering ASC

mapper.update:
UPDATE content
SET
     title = #{title}
    ,body = #{body}
    ,visible_yn = #{visibleYn}
    ,last_update_date = NOW()
WHERE content_id = #{contentId}

